import React, { useState, useEffect } from 'react';
import axios from 'axios';
import AddBook from './AddBook';
import BookCard from './BookCard';

function BookList({ user, showToast }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState('');

  const fetchBooks = () => {
    const token = localStorage.getItem('token');
    axios.get('http://localhost:5000/api/books', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => setBooks(res.data))
      .catch(() => setError('Failed to fetch books'));
  };

  useEffect(() => {
    fetchBooks();
  }, []);

  const requestBook = async (bookId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post('http://localhost:5000/api/requests', {
        bookId
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (showToast) showToast('Request sent!');
    } catch (err) {
      if (showToast) showToast(err.response?.data?.message || 'Failed to request book');
    }
  };

  const handleAddBook = () => {
    fetchBooks();
  };

  return (
    <div className="max-w-2xl mx-auto mt-8 bg-white rounded-xl shadow-xl p-6">
      <div className="text-2xl font-bold mb-4 text-gray-800">Available Books</div>
      {user?.role === 'librarian' && (
        <AddBook onAdd={handleAddBook} showToast={showToast} />
      )}
      {error && <p className="text-red-600 mb-4">{error}</p>}
      <div className="space-y-4">
        {books.map(book => (
          <BookCard key={book._id} book={book} user={user} onRequest={requestBook} />
        ))}
      </div>
    </div>
  );
}

export default BookList;
